---刚打开时  只显示 + 号  点击 + 号显示左侧列表  点击列表 显示 食物
function OverseaManageMenuSettingFoodTypeCell:InitFoodItem(tabIndex ,index)
    self.tabIndex = tabIndex
    self.index = index
    self:Init()
    self.isUnLocked,self.LockNum = maidCoffeeComponent:IsMenuSlotUnLockAndLockLevel(self.tabIndex,self.index)
    if not self.isUnLocked then
        CfUtils.FillText(self.LockLevel,self.LockNum)
        self.lockDes = localize("咖啡厅_num_级解锁",{_num_ = self.LockNum})
        KTool.SetActive(self.StatusLock.gameObject,true)
        return
    end
    KTool.SetActive(self.ImgAdd.gameObject,true)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo =  component:GetMaidCoffeeHomeDoJo()
    local type = maidCoffeeHomeDojo:GetSaleType(self.tabIndex,self.index)
    self.ImgAdd.Status = type
    self.AddType.Status = type
    self.data = nil
end

function OverseaManageMenuSettingFoodTypeCell:PlayAniByName(AniName)
    if AniName then
        self.Content:Play(AniName)
    end

end

function OverseaManageMenuSettingFoodTypeCell:OnSelect()
    KTool.SetActive(self.Select.gameObject,true)
end

function OverseaManageMenuSettingFoodTypeCell:DoSelect()
    KTool.SetActive(self.Select.gameObject,false)
end

--[[| M   | \\-- *recipeId*   | int  | 菜谱id                    |
| M   | \\-- *rating*     | int  | 评级 (D=1,C=2,B=3,A=4,S=5                     |
| M   | \\-- *price*      | int  | 最终售价                    |
| M   | \\-- *isDouble*   | int  | 是1否0受到加成                |]]
---这个方法是在上架页面调用
function OverseaManageMenuSettingFoodTypeCell:RefreshPutFoodTypeShow(data)
    self.data = clone(data)
    KTool.SetActive(self.Content.gameObject,true)
    KTool.SetActive(self.ImgBg.gameObject,true)
    KTool.SetActive(self.ImgEllipse.gameObject,true)
    local menuVo = MaidCoffeeUtils.GetMaidCoffeeMenuMakeVo(self.data.recipeId)
    self.vo = GoodsConfMgr:GetInstance():GetGoodsVoById(menuVo.foodId)

    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local rate = maidCoffeeComponent:GetPriceRate()
    self.data.price = math.floor(checkNumber(self.data.price) * rate)
    self:SetFoodInfo(self.data)
end

function OverseaManageMenuSettingFoodTypeCell:SetItemShow(data)
    self.data = data
    KTool.SetActive(self.ImgAdd.gameObject,false)
    KTool.SetActive(self.Content.gameObject,true)
    self.vo =  GoodsConfMgr:GetInstance():GetGoodsVoById(data.foodId)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local isDouble = component:IsMenuDouble(self.tabIndex,self.index,data.refId)
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local serverInfo = maidCoffeePlayerComponent:GetRecipeDoJoById(data.refId)
    local price = component:GetMenuFoodPrice(self.tabIndex,self.index,data.refId)
    local data = {
        isDouble = isDouble and 1 or 0,recipeId = data.refId,rating = serverInfo.rating, price = price
    }
    self:SetFoodInfo(data)
end

function OverseaManageMenuSettingFoodTypeCell:IsInActivity()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local homeDojo = component:GetMaidCoffeeHomeDoJo()
    local isInActivity = homeDojo:IsActivity()
    return isInActivity
end

function OverseaManageMenuSettingFoodTypeCell:SetFoodInfo(data)
    if isNull(self.vo) then return end
    ---加载图片
    CfUtils.FillImage(self.ImgIcon, self.vo.photoPath)
    CfUtils.FillImage(self.ImgIcon2,self.vo.photoPath)

    ---品质
    self.ImgQuality.Status = data.rating or 1

    ---名字 1中文  2英文
    CfUtils.FillText(self.TextName1,self.vo.name)
    ---货币和图标
    local goodsId = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(7).num
    ---@type GoodsVo
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    CfUtils.FillImage(self.ImgGoodsIcon, goodsVo.photoPath)
    CfUtils.FillText(self.TextNumber,math.floor(data.price))
    ---是否是双倍
    KTool.SetActive(self.Addition.gameObject,true)

    local isDouble = data.isDouble == 1
    local state = isDouble and 2 or 1
    CfUtils.SetUISwitchText(self.DoubleTxt,state)
    CfUtils.SetUISwitchImage(self.AddImgBg,state)

    local isInActivity = self:IsInActivity()
    KTool.SetActive(self.ImgYellowUP.gameObject,isInActivity)
end

function OverseaManageMenuSettingFoodTypeCell:OnBtnNodeClick()
    if self.isShowLock then
        if not self.isUnLocked then
            GameUtils.Toast(self.lockDes)
            return
        end
    end
    if not isNull(self.callBack) then
        self:OnSelect()
        self.callBack(self.index)
    end
end

function OverseaManageMenuSettingFoodTypeCell:RefreshPosAndScale(posAndScale)
    self.BtnNode.transform.parent.transform.localPosition = Vector3.New(posAndScale.pos[1],posAndScale.pos[2],0)
    self.BtnNode.transform.parent.transform.localScale = Vector3.New(posAndScale.scale,posAndScale.scale,posAndScale.scale)
end

